618	  #dispatch(action: Action<TData, TError>): void {
619	    const reducer = (
620	      state: QueryState<TData, TError>,
621	    ): QueryState<TData, TError> => {
622	      switch (action.type) {
623	        case 'failed':
624	          return {
625	            ...state,
626	            fetchFailureCount: action.failureCount,
627	            fetchFailureReason: action.error,
628	          }
629	        case 'pause':
630	          return {
631	            ...state,
632	            fetchStatus: 'paused',
633	          }
634	        case 'continue':
635	          return {
636	            ...state,
637	            fetchStatus: 'fetching',
638	          }
639	        case 'fetch':
640	          return {
641	            ...state,
642	            ...fetchState(state.data, this.options),
643	            fetchMeta: action.meta ?? null,
644	          }
645	        case 'success':
646	          const newState = {
647	            ...state,
648	            ...successState(action.data, action.dataUpdatedAt),
649	            dataUpdateCount: state.dataUpdateCount + 1,
650	            ...(!action.manual && {
651	              fetchStatus: 'idle' as const,
652	              fetchFailureCount: 0,
653	              fetchFailureReason: null,
654	            }),
655	          }
656	          // If fetching ends successfully, we don't need revertState as a fallback anymore.
657	          // For manual updates, capture the state to revert to it in case of a cancellation.
658	          this.#revertState = action.manual ? newState : undefined
659	
660	          return newState
661	        case 'error':
662	          const error = action.error
663	          return {
664	            ...state,
665	            error,
666	            errorUpdateCount: state.errorUpdateCount + 1,
667	            errorUpdatedAt: Date.now(),
668	            fetchFailureCount: state.fetchFailureCount + 1,
669	            fetchFailureReason: error,
670	            fetchStatus: 'idle',
671	            status: 'error',
672	            // flag existing data as invalidated if we get a background error
673	            // note that "no data" always means stale so we can set unconditionally here
674	            isInvalidated: true,
675	          }
676	        case 'invalidate':
677	          return {
678	            ...state,
679	            isInvalidated: true,
680	          }
681	        case 'setState':
682	          return {
683	            ...state,
684	            ...action.state,
685	          }
686	      }
687	    }
